<template><div class="sd-panel-tabs"><div class="sd-tab-wrap" role="tablist"><button v-for="a in artifacts" :key="a.id" class="sd-panel-tab" :aria-selected="!agentActive && a.id===activeId" @click="selectArtifact(a.id)">{{ a.name }}</button><button v-if="showAgent" class="sd-panel-tab" :aria-selected="agentActive" @click="emit('agent-select')">Agent</button><span class="sd-tab-indicator" :style="indicatorStyle"/></div><span class="spacer"/><button class="sd-icon" title="Close panel" aria-label="Close panel" @click="emit('collapse')">×</button></div></template>
<script setup lang="ts">import { computed } from 'vue';import { useChatController } from '../../controller/useChatController';const props=defineProps<{showAgent?:boolean;agentActive?:boolean}>(),emit=defineEmits<{collapse:[];'agent-select':[];'artifact-select':[]}>(),controller=useChatController(),artifacts=computed(()=>controller.artifacts.value.list),activeId=computed(()=>controller.artifacts.value.activeId),selectedIndex=computed(()=>props.agentActive?artifacts.value.length:Math.max(0,artifacts.value.findIndex(a=>a.id===activeId.value))),indicatorStyle=computed(()=>({width:`calc((100% - 4px * ${Math.max(0,artifacts.value.length+(props.showAgent?1:0)-1)}) / ${Math.max(1,artifacts.value.length+(props.showAgent?1:0))})`,transform:`translateX(calc(${selectedIndex.value} * (100% + 4px)))`}));function selectArtifact(id:string){controller.switchArtifact(id);emit('artifact-select')}</script>
<style scoped>.sd-panel-tabs{display:flex;align-items:center;gap:4px;padding:10px 10px 6px 12px;border-bottom:1px solid var(--border-default)}.sd-tab-wrap{position:relative;display:flex;gap:4px;min-width:0;overflow:hidden}.sd-panel-tab{height:32px;max-width:125px;padding:0 10px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;border:0;border-radius:10px;background:transparent;color:var(--text-secondary);font-size:13px;cursor:pointer}.sd-panel-tab:hover{color:var(--text-primary)}.sd-panel-tab[aria-selected=true]{color:var(--accent-primary);font-weight:500}.sd-tab-indicator{position:absolute;bottom:0;height:2px;border-radius:2px;background:var(--accent-primary);transition:transform 580ms linear(0,.006,.025 2.8%,.101 6.1%,.539 18.9%,.849 31.5%,.968 41.8%,1.006 50.1%,1.017 63.9%,1),width 580ms}.spacer{flex:1}.sd-icon{width:32px;height:32px;border:0;border-radius:8px;background:transparent;color:var(--text-secondary);font-size:20px;cursor:pointer}.sd-icon:hover{background:var(--bg-surface-alt);color:var(--text-primary)}</style>
